{
  "PROP-6a4369e9-asm-001": {
    "property_id": "PROP-6a4369e9-asm-001",
    "audit_result": {
      "property_id": "PROP-6a4369e9-asm-001",
      "classification": "vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_availability_checker.rs::verify_kzg_for_rpc_blocks::L434-448",
      "proof_trace": "RPC/sync data columns from untrusted P2P peers bypass full validation. Gossip path enforces signature verification, proposer checks, and inclusion proofs (L479-508), but RPC custody columns receive only KZG validation (L446), skipping all cryptographic authenticity checks.",
      "attack_scenario": "Attacker responds to DataColumnsByRange with columns having valid KZG proofs but forged signatures or invalid merkle proofs. Columns pass KZG check (L446), get marked available (L467-475), and could be reconstructed or propagated without detecting the forgery.",
      "checklist_id": "PROP-6a4369e9-asm-001"
    },
    "text": "P2P peers are untrusted; all P2P input must be fully validated before acceptance.",
    "assertion": "forall msg from P2P: processed(msg) => fully_validated(msg) == true",
    "covers": "SG-006",
    "severity": "HIGH",
    "type": "assumption"
  }
}

